CREATE OR REPLACE FUNCTION public.upsert_laundry_route_preparation_checked(_task_id uuid, _share_link_id uuid, _action text, _issue_reason text, _route_worker_id uuid, _cleaner_id uuid, _worker_name text, _content_snapshot jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  route_link public.laundry_share_links;
  task_row public.tasks;
  route_enabled boolean;
  preparation_id uuid;
  action_time timestamptz := clock_timestamp();
BEGIN
  IF _action NOT IN ('prepare','issue') OR _task_id IS NULL OR _share_link_id IS NULL THEN
    RAISE EXCEPTION 'Invalid laundry route preparation action';
  END IF;
  -- Match the physical RPC's order. A cancellation/reschedule cannot land
  -- between the server check and the one atomic preparation row write.
  SELECT * INTO route_link FROM public.laundry_share_links
    WHERE id=_share_link_id AND is_active AND workflow_version='route_v2'
      AND (expires_at IS NULL OR expires_at>now()) FOR UPDATE;
  IF route_link.id IS NULL THEN RAISE EXCEPTION 'Active route link not found'; END IF;
  SELECT * INTO task_row FROM public.tasks WHERE id=_task_id FOR UPDATE;
  IF task_row.id IS NULL OR task_row.sede_id IS DISTINCT FROM route_link.sede_id
    OR task_row.propiedad_id IS NULL OR task_row.type <> 'limpieza-turistica'
    OR task_row.status='cancelled' OR NOT (_task_id=ANY(route_link.snapshot_task_ids)) THEN
    RAISE EXCEPTION 'Cleaning no longer belongs to this route';
  END IF;
  IF NOT (
    (jsonb_typeof(route_link.filters->'routeDates')='array'
      AND EXISTS (SELECT 1 FROM jsonb_array_elements_text(route_link.filters->'routeDates') d
        WHERE d.value=task_row.date::text))
    OR (jsonb_typeof(route_link.filters->'nextRouteDates')='array'
      AND EXISTS (SELECT 1 FROM jsonb_array_elements_text(route_link.filters->'nextRouteDates') d
        WHERE d.value=task_row.date::text))
  ) THEN RAISE EXCEPTION 'Cleaning was rescheduled outside this route'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.properties p
    WHERE p.id=task_row.propiedad_id AND p.sede_id=task_row.sede_id) THEN
    RAISE EXCEPTION 'Cleaning property is not in its route sede';
  END IF;
  SELECT coalesce(s.laundry_route_inventory_enabled,false) INTO route_enabled
    FROM public.stock_sede_settings s WHERE s.sede_id=route_link.sede_id FOR SHARE;
  IF route_enabled AND _route_worker_id IS NULL THEN
    RAISE EXCEPTION 'A PIN-authenticated route worker is required';
  END IF;
  IF _route_worker_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.laundry_route_workers rw
    WHERE rw.id=_route_worker_id AND rw.cleaner_id=_cleaner_id
      AND rw.sede_id=route_link.sede_id AND rw.is_active) THEN
    RAISE EXCEPTION 'Invalid route worker';
  END IF;
  IF _action='issue' AND length(trim(coalesce(_issue_reason,'')))<3 THEN
    RAISE EXCEPTION 'Issue reason must have at least three characters';
  END IF;
  IF _action='prepare' AND (jsonb_typeof(_content_snapshot) IS DISTINCT FROM 'object'
    OR coalesce(_content_snapshot->>'taskId','')<>_task_id::text) THEN
    RAISE EXCEPTION 'An identified server-computed bag snapshot is required';
  END IF;
  INSERT INTO public.laundry_bag_preparations(
    task_id,status,last_share_link_id,updated_at,route_novelty_resolved,
    content_snapshot,snapshot_locked_at,prepared_at,prepared_by_name,prepared_by_worker_id,
    issue_at,issue_by_name,issue_by_worker_id,issue_reason)
  VALUES(_task_id,CASE WHEN _action='prepare' THEN 'prepared' ELSE 'issue' END,
    route_link.id,action_time,true,
    CASE WHEN _action='prepare' THEN _content_snapshot ELSE '{}'::jsonb END,
    CASE WHEN _action='prepare' THEN action_time ELSE NULL END,
    CASE WHEN _action='prepare' THEN action_time ELSE NULL END,
    CASE WHEN _action='prepare' THEN coalesce(nullif(trim(_worker_name),''),'Lavandería') ELSE NULL END,
    CASE WHEN _action='prepare' THEN _cleaner_id ELSE NULL END,
    CASE WHEN _action='issue' THEN action_time ELSE NULL END,
    CASE WHEN _action='issue' THEN coalesce(nullif(trim(_worker_name),''),'Lavandería') ELSE NULL END,
    CASE WHEN _action='issue' THEN _cleaner_id ELSE NULL END,
    CASE WHEN _action='issue' THEN trim(_issue_reason) ELSE NULL END)
  ON CONFLICT(task_id) DO UPDATE SET
    status=EXCLUDED.status,last_share_link_id=EXCLUDED.last_share_link_id,
    updated_at=action_time,route_novelty_resolved=true,
    content_snapshot=CASE WHEN _action='prepare' THEN EXCLUDED.content_snapshot
      ELSE public.laundry_bag_preparations.content_snapshot END,
    snapshot_locked_at=CASE WHEN _action='prepare' THEN action_time
      ELSE public.laundry_bag_preparations.snapshot_locked_at END,
    prepared_at=CASE WHEN _action='prepare' THEN action_time
      ELSE public.laundry_bag_preparations.prepared_at END,
    prepared_by_name=CASE WHEN _action='prepare' THEN EXCLUDED.prepared_by_name
      ELSE public.laundry_bag_preparations.prepared_by_name END,
    prepared_by_worker_id=CASE WHEN _action='prepare' THEN _cleaner_id
      ELSE public.laundry_bag_preparations.prepared_by_worker_id END,
    issue_at=EXCLUDED.issue_at,issue_by_name=EXCLUDED.issue_by_name,
    issue_by_worker_id=EXCLUDED.issue_by_worker_id,issue_reason=EXCLUDED.issue_reason
  RETURNING id INTO preparation_id;
  RETURN jsonb_build_object('preparationId',preparation_id,'taskId',_task_id,
    'status',CASE WHEN _action='prepare' THEN 'prepared' ELSE 'issue' END);
END;
$function$
